   47	    /** A partial report on a valuable target gets this many probes; the host redacts ships below two and defence below three probes, so one probe re-reads the same redacted report. */
   48	    private const ESCALATED_PROBES = 5;
   49	
   50	    /** Metal-equivalent loot that makes a redacted report worth a probe volley. */
   51	    private const RICH_YIELD = 10_000.0;
