  5	use Modules\AI\Domain\Raid\RaidEstimate;
  6	use OGame\Factories\PlanetServiceFactory;
  7	use OGame\Factories\PlayerServiceFactory;
  8	use OGame\GameMissions\BattleEngine\BattleEngine;
  9	use OGame\GameMissions\BattleEngine\Models\AttackerFleet;
 10	use OGame\GameMissions\BattleEngine\Models\DefenderFleet;
 11	use OGame\GameMissions\BattleEngine\RustBattleEngine;
 12	use OGame\GameObjects\Models\Units\UnitCollection;
 13	use OGame\Models\Resources;
 14	use OGame\Services\SettingsService;
 15	
 16	/**
 17	 * The native raid estimator: samples the host's own battle engine as a read-only
 18	 * question.
 19	 *
 20	 * It is not a second battle implementation. Every run asks
 21	 * `simulateBattle($seed, true)` — the pure, seeded shape R1 added — on the engine
 22	 * the host itself fights with (`SettingsService::battleEngine()`), so the engine
 23	 * stays the authority on the rules and a "what if" never touches the world. Both
 24	 * engines are seeded: the Rust FFI carries the seed in its input and derives one
 25	 * stream per side per round, so a screen replays identically whichever engine the
 26	 * universe runs. Rust is roughly 7x faster per simulation, which is why the
 27	 * module no longer pins the PHP engine.
 28	 *
 29	 * The fleet is the account's own ships on the origin planet, and the defender is
 30	 * the host's stationary picture of the target planet, so no unit, price or
 31	 * defence figure is named here.
 32	 */
 33	class NativeRaidEstimator
 34	{
 35	    private const SCREEN_SAMPLES = 50;
 36	
 37	    private const CRYSTAL_WEIGHT = 1.5;
 38	
 39	    private const DEUTERIUM_WEIGHT = 2.0;
 40	
 41	    public function __construct(
 42	        private PlayerServiceFactory $playerServiceFactory,
 43	        private PlanetServiceFactory $planetServiceFactory,
 44	        private SettingsService $settings,
 45	    ) {
 46	    }
 47	
 48	    public function estimate(int $playerId, int $originPlanetId, int $targetPlanetId, int $seed): RaidEstimate
 49	    {
 50	        return $this->screen($playerId, $originPlanetId, $targetPlanetId, null, $seed, self::SCREEN_SAMPLES);
 51	    }
 52	
 53	    /**
 54	     * One simulation of a specific fleet against the target — the launch-subset screen (U6). The
 55	     * fleet is what the caller counter-selected; the engine and the defender stay the host's. The
 56	     * sample count is the caller's ladder rung: one draw for a candidate screen, the wide pass for
 57	     * the winner's confirmation.
 58	     */
 59	    public function estimateFleet(int $playerId, int $originPlanetId, int $targetPlanetId, UnitCollection $fleet, int $seed, int $samples = 1): RaidEstimate
 60	    {
 61	        return $this->screen($playerId, $originPlanetId, $targetPlanetId, $fleet, $seed, $samples);
 62	    }
 63	
 64	    private function screen(int $playerId, int $originPlanetId, int $targetPlanetId, ?UnitCollection $fleet, int $seed, int $samples): RaidEstimate
 65	    {
 66	        $player = $this->playerServiceFactory->make($playerId, true);
 67	        $origin = $this->planetServiceFactory->makeForPlayer($player, $originPlanetId, false);
 68	        $target = $this->planetServiceFactory->make($targetPlanetId, true);
 69	
 70	        if ($target === null) {
 71	            return app()->makeWith(RaidEstimate::class, [
 72	                'samples' => 0,
 73	                'p20NetProfit' => 0.0,
 74	                'p20Loot' => 0.0,
 75	                'pWin' => 0.0,
 76	            ]);
 77	        }
 78	
 79	        $ships = $fleet ?? $origin->getShipUnits();
 80	        if ($ships->units === []) {
 81	            return app()->makeWith(RaidEstimate::class, [
 82	                'samples' => 0,
 83	                'p20NetProfit' => 0.0,
 84	                'p20Loot' => 0.0,
 85	                'pWin' => 0.0,
 86	            ]);
 87	        }
 88	
 89	        $attacker = new AttackerFleet();
 90	        $attacker->units = $ships;
 91	        $attacker->player = $player;
 92	        $attacker->fleetMissionId = 0;
 93	        $attacker->ownerId = $playerId;
 94	        $attacker->cargoResources = new Resources();
 95	        $attacker->isInitiator = true;
 96	        $attacker->fleetMission = null;
 97	
 98	        $defender = DefenderFleet::fromPlanet($target);
 99	
100	        // The Rust engine is the one the universe fights with, so it is the only one the estimate runs.
101	        $engine = new RustBattleEngine([$attacker], $target, [$defender], $this->settings);
102	
103	        // The screen is the one bounded pass the decision path may afford; the
104	        // confirmation is a wider sample on the winner only.
105	        $sampled = $this->sample($engine, $seed, $samples);
106	
107	        return app()->makeWith(RaidEstimate::class, [
108	            'samples' => count($sampled['netProfits']),
109	            'p20NetProfit' => $this->lowerQuantile($sampled['netProfits'], 0.2),
110	            'p20Loot' => $this->lowerQuantile($sampled['loots'], 0.2),
111	            'pWin' => $sampled['survived'] / max(1, count($sampled['netProfits'])),
112	        ]);
113	    }
114	
115	    /**
116	     * One bounded screen: the same seed + i stream yields the P20 net (survival),
117	     * the P20 loot (worth-flying) and the survived-run count (fleet survival)
118	     * from identical draws — never a second pass.
119	     *
120	     * @return array{netProfits: list<float>, loots: list<float>, survived: int}
121	     */
122	    private function sample(BattleEngine $engine, int $seed, int $samples): array
123	    {
124	        $netProfits = [];
125	        $loots = [];
126	        $survived = 0;
127	
128	        for ($i = 0; $i < $samples; $i++) {
129	            // One shared stream: seed + i, so a candidate is always compared
130	            // through the same sequence of draws.
131	            $result = $engine->simulateBattle($seed + $i, true);
132	
133	            $loots[] = $this->metalEquivalent($result->loot);
134	            $netProfits[] = $loots[$i] - $this->metalEquivalent($result->attackerResourceLoss);
135	
136	            // getAmount(), not ->units === []: the round sanitizer keeps
137	            // zero-amount entries, so a wiped fleet reads as an empty amount.
138	            $survived += $result->attackerUnitsResult->getAmount() > 0 ? 1 : 0;
139	        }
140	
141	        return ['netProfits' => $netProfits, 'loots' => $loots, 'survived' => $survived];
142	    }
143	
144	    /**
145	     * @param list<float> $values
146	     */
147	    private function lowerQuantile(array $values, float $quantile): float
148	    {
149	        sort($values);
150	        $rank = (int) ceil($quantile * count($values)) - 1;
151	
152	        return $values[max(0, min($rank, count($values) - 1))];
153	    }
154	
155	    public function metalEquivalent(Resources $resources): float
156	    {
157	        return $resources->metal->get()
158	            + self::CRYSTAL_WEIGHT * $resources->crystal->get()
159	            + self::DEUTERIUM_WEIGHT * $resources->deuterium->get();
160	    }
161	}

