 36	    /** @return array<int, ScoredCandidate> */
 37	    public function score(AiProfile $profile, CandidateGeneration $generation, string $decisionKey): array
 38	    {
 39	        $policy = $this->policyRegistry->for($profile->archetype);
 40	        $affectWeight = (float) app(AiRuntimeSettings::class)->affectDecisionWeight();
 41	        // One mood read per decision, never per candidate, and only when the opt-in weight is
 42	        // on: the default path performs no affect query and changes no score.
 43	        $appetite = $affectWeight > 0.0 ? $this->threatAppetite($profile) : 0.0;
 44	        $scored = [];
 45	        foreach ($generation->candidates as $candidate) {
 46	            if (!$policy->allows($candidate->type)) {
 47	                continue;
 48	            }
 49	
 50	            $features = $candidate->features;
 51	            $variation = ($this->randomSource->unitInterval($profile->random_seed, $decisionKey . ':' . $candidate->type->value) - 0.5) * $profile->skill_band->variationWeight();
 52	            $components = [
 53	                'resource_need' => $features['resource_need'] * self::RESOURCE_NEED_WEIGHT,
 54	                'safety' => $features['safety'] * self::SAFETY_WEIGHT,
 55	                'target_confidence' => $features['target_confidence'] * self::TARGET_CONFIDENCE_WEIGHT,
 56	                'travel_cost' => -$features['travel_cost'] * self::TRAVEL_COST_WEIGHT,
 57	                'recovery' => $features['recovery'] * self::RECOVERY_WEIGHT,
 58	                'archetype_preference' => $policy->preference($candidate->type) * self::ARCHETYPE_WEIGHT,
 59	                'seeded_variation' => $variation,
 60	                'affect' => $appetite * $this->appetiteDirection($candidate->type) * $affectWeight,
 61	            ];
 62	            $scored[] = app()->makeWith(ScoredCandidate::class, [
 63	                'candidate' => $candidate,
 64	                'score' => array_sum($components),
 65	                'components' => $components,
 66	            ]);
 67	        }
 68	
 69	        // A stable secondary key prevents an otherwise identical replay from
 70	        // changing only because PHP received candidates in a different order.
 71	        usort($scored, static fn (ScoredCandidate $left, ScoredCandidate $right): int => $right->score <=> $left->score ?: $left->candidate->type->value <=> $right->candidate->type->value);
 72	
 73	        return $scored;
 74	    }
 75	
 76	    /**
 77	     * The account's current mood as a signed appetite: anger presses the attack, fear presses
 78	     * the save, and the skill band decides how fully the account plays the feeling. The value
 79	     * stays inside [-1, 1] so the opt-in weight alone bounds what a mood can move.
 80	     */
 81	    private function threatAppetite(AiProfile $profile): float
 82	    {
 83	        $now = $this->clock->now();
 84	        $anger = $this->currentAffectIntensity->handle($profile->player_id, AiAffectEmotion::Anger, $now);
 85	        $fear = $this->currentAffectIntensity->handle($profile->player_id, AiAffectEmotion::Fear, $now);
 86	
 87	        return max(-1.0, min(1.0, ($anger - $fear) * $profile->skill_band->evidenceReaction()));
 88	    }
 89	
 90	    /**
 91	     * Which way a candidate type leans on the appetite: an attack wants anger, a save or
 92	     * fleetsave wants caution, and everything else is a routine step the mood leaves alone.
 93	     */
 94	    private function appetiteDirection(AiCandidateActionType $type): int
 95	    {
 96	        return match ($type) {
 97	            AiCandidateActionType::Raid => 1,
 98	            AiCandidateActionType::FleetSave => -1,
 99	            default => 0,
100	        };
101	    }
102	
103	    /** @param array<int, ScoredCandidate> $candidates */
104	    public function select(AiProfile $profile, array $candidates, string $decisionKey): ScoredCandidate
105	    {
106	        $best = $candidates[0];
107	        // Skill affects choice among close options, never whether a clearly
108	        // superior safety or economy decision is eligible to win.
109	        $nearEqual = array_values(array_filter(
110	            $candidates,
111	            static fn (ScoredCandidate $candidate): bool => $candidate->score >= $best->score - $profile->skill_band->selectionMargin(),
112	        ));
113	        $index = (int) floor($this->randomSource->unitInterval($profile->random_seed, $decisionKey . ':select') * count($nearEqual));
114	
115	        return $nearEqual[min($index, count($nearEqual) - 1)];
116	    }
